import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/tmp');sys.path.insert(0,'/workspace/submission')
from genfast_lifo_d4 import GenFast
from pr import push_relabel_cutoff
# build nt300 deterministic
def build(nt,seed):
 random.seed(seed);n=32
 H=nx.DiGraph();H.add_nodes_from(range(n));loads={};roots={i:0 for i in range(n)}
 for k in range(nt):
  T=[]
  for v in range(1,n):T.append((random.randrange(v),v))
  root=random.randrange(n);w=random.randint(1,10)
  adj={i:[] for i in range(n)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:seen.add(y);loads[(x,y)]=loads.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
 return H,roots
for nt in [300,1000]:
 H,roots=build(nt,9000+nt);g=GenFast(H,list(range(32)),roots);t=time.time();Ts,Cs=g.generate();print(nt,'time',time.time()-t,'trees',len(Ts),'calls',g.calls,'maxact',g.max_active,'maxedges',g.max_edges,'mf',g.time_mf)
